<?php require_once __DIR__ . '/../auth/guard.php'; requireRole('student'); ?>
<style>
.kidss-achievements{padding:8px 2px 28px;color:#24355f}.kidss-achievements h1{font-size:1.8rem;font-weight:850}.ka-muted{color:#6b7280}.ka-summary{background:#fff;border:1px solid #e8ebf3;border-radius:18px;padding:20px;margin:18px 0}.ka-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.ka-card{background:#fff;border:1px solid #e8ebf3;border-radius:18px;padding:20px}.ka-icon{width:54px;height:54px;border-radius:15px;background:#f1eaff;color:#7048e8;display:grid;place-items:center;font-size:1.5rem;margin-bottom:14px}.ka-card.locked{opacity:.72}.ka-bar{height:8px;background:#eceaf5;border-radius:10px;overflow:hidden}.ka-bar span{display:block;height:100%;background:#7048e8}@media(max-width:850px){.ka-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:580px){.ka-grid{grid-template-columns:1fr}}
</style>
<div class="kidss-achievements"><h1>My Achievements</h1><p class="ka-muted">Badges are awarded from your saved lesson and quiz activity.</p><div id="achievementNotice" class="alert d-none" role="status"></div><div id="achievementSummary" class="ka-summary">Loading earned achievements…</div><div id="achievementGrid" class="ka-grid"></div></div>
<script>
(function(){const ep='api/student_achievements.php',grid=document.getElementById('achievementGrid'),summary=document.getElementById('achievementSummary'),notice=document.getElementById('achievementNotice');if(!grid||grid.dataset.bound)return;grid.dataset.bound='1';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const icons=['bi-stars','bi-trophy-fill','bi-award-fill','bi-book-fill','bi-patch-check-fill'];
async function load(){try{const r=await fetch(ep,{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message);summary.innerHTML='<strong>'+Number(d.unlocked)+' / '+Number(d.total)+' achievements earned</strong><div class="ka-bar mt-3"><span style="width:'+(d.total?Math.round(d.unlocked/d.total*100):0)+'%"></span></div>';grid.innerHTML=d.achievements.length?d.achievements.map((a,i)=>'<article class="ka-card '+(a.unlocked?'':'locked')+'"><div class="ka-icon"><i class="bi '+esc(a.icon||icons[i%icons.length])+'"></i></div><span class="badge '+(a.unlocked?'text-bg-success':'text-bg-secondary')+'">'+(a.unlocked?'Earned':'In progress')+'</span><h2 class="h5 fw-bold mt-3">'+esc(a.name)+'</h2><p class="ka-muted">'+esc(a.description||'Keep learning to unlock this badge.')+'</p><div class="ka-bar"><span style="width:'+(a.target?Math.min(100,Number(a.progress)/Number(a.target)*100):0)+'%"></span></div><small class="ka-muted">'+Number(a.progress)+' / '+Number(a.target)+' progress'+(a.earned_at?' · Earned '+esc(a.earned_at):'')+'</small></article>').join(''):'<div class="ka-card">No active achievements have been configured by your administrator yet.</div>'}catch(e){notice.className='alert alert-danger';notice.textContent=e.message;summary.textContent='Unable to load achievements.'}}
load()})();
</script>